import { escapeExpression } from "./ffmpegExpressions";

/** Parse the filter options generated by the render compiler, respecting quoted expressions. */
export function aces16FilterOptionsV1(text: string): Record<string, string> {
  const parts: string[] = [];
  let part = "", quote = "", escaped = false;
  for (const char of text) {
    if (escaped) { part += char; escaped = false; continue; }
    if (char === "\\") { part += char; escaped = true; continue; }
    if (char === "'" || char === '"') {
      if (quote === char) quote = "";
      else if (!quote) quote = char;
      part += char;
    } else if (char === ":" && !quote) { parts.push(part); part = ""; }
    else part += char;
  }
  if (quote || escaped) throw Error("Unterminated internal ACES filter expression");
  parts.push(part);
  const result: Record<string, string> = {};
  for (const entry of parts) {
    const equal = entry.indexOf("="), key = entry.slice(0, equal);
    if (equal < 1 || !/^[a-z][a-z0-9_]*$/.test(key) || Object.hasOwn(result, key)) throw Error("Invalid internal ACES filter option");
    let value = entry.slice(equal + 1);
    if (value.length >= 2 && ["'", '"'].includes(value[0]) && value.at(-1) === value[0]) value = value.slice(1, -1);
    result[key] = value.replace(/\\([\\,;:'"])/g, "$1");
  }
  return result;
}

/** Mathematical cubic-convolution kernel; A=-0.6 matches the selected perspective renderer. */
function cubicWeight(distance: string): string {
  const d = `abs(${distance})`;
  return `if(lt(${d},1),1-2.4*pow(${d},2)+1.4*pow(${d},3),if(lt(${d},2),2.4-4.8*${d}+3*pow(${d},2)-.6*pow(${d},3),0))`;
}

function sample(channel: string, cubic: boolean): string {
  if (!cubic) return `${channel}(ld(4),ld(5))`;
  const fx = "(ld(4)-floor(ld(4)))", fy = "(ld(5)-floor(ld(5)))";
  const terms: string[] = [];
  for (let y = -1; y <= 2; y++) for (let x = -1; x <= 2; x++) {
    terms.push(`(${cubicWeight(`${fx}-(${x})`)})*(${cubicWeight(`${fy}-(${y})`)})*${channel}(floor(ld(4))+(${x}),floor(ld(5))+(${y}))`);
  }
  return `clip(${terms.join("+")},0,65535)`;
}

/**
 * Inverse projective sampling on GBRAP16. The bundled perspective filter admits
 * only 8-bit RGB; this implementation keeps its source/destination corner sense,
 * cubic-convolution parameter and one-based in/on corner-expression clock.
 * It uses the mathematical quadrilateral homography, not a low-depth intermediate.
 */
export function aces16PerspectiveFilterV1(filter: string): string {
  if (!filter.startsWith("perspective=")) throw Error("Expected an internal perspective filter");
  const o = aces16FilterOptionsV1(filter.slice("perspective=".length));
  const allowed = new Set(["x0", "y0", "x1", "y1", "x2", "y2", "x3", "y3", "sense", "interpolation", "eval"]);
  if (Object.keys(o).some(k => !allowed.has(k))) throw Error("Unsupported internal perspective option");
  if (o.sense && !["source", "destination", "0", "1"].includes(o.sense)) throw Error("Invalid perspective corner sense");
  if (o.interpolation && !["linear", "cubic", "0", "1"].includes(o.interpolation)) throw Error("Invalid perspective interpolation");
  if (o.eval && !["init", "frame", "0", "1"].includes(o.eval)) throw Error("Invalid perspective evaluation clock");
  const frame = o.eval === "frame" || o.eval === "1";
  const expression = (value: string) => value.replace(/\b(?:on|in)\b/g, frame ? "(N+1)" : "1");
  const points = [o.x0 ?? "0", o.y0 ?? "0", o.x1 ?? "W", o.y1 ?? "0", o.x2 ?? "0", o.y2 ?? "H", o.x3 ?? "W", o.y3 ?? "H"];
  // Registers0..7 initially hold the four corners. Registers8/9 hold the
  // projective coefficients. Once those are known, unused corner registers
  // become the affine coefficients and source sampling coordinates.
  const setup = points.map((p, i) => `st(${i},(${expression(p)}))`);
  const dx1 = "(ld(2)-ld(6))", dx2 = "(ld(4)-ld(6))", dx3 = "(ld(0)-ld(2)-ld(4)+ld(6))";
  const dy1 = "(ld(3)-ld(7))", dy2 = "(ld(5)-ld(7))", dy3 = "(ld(1)-ld(3)-ld(5)+ld(7))";
  const determinant = `(${dx1}*${dy2}-${dx2}*${dy1})`;
  setup.push(`st(8,(${dx3}*${dy2}-${dx2}*${dy3})/${determinant})`);
  setup.push(`st(9,(${dx1}*${dy3}-${dx3}*${dy1})/${determinant})`);
  setup.push("st(6,ld(2)-ld(0)+ld(8)*ld(2))"); // a
  setup.push("st(7,ld(4)-ld(0)+ld(9)*ld(4))"); // b
  setup.push("st(2,ld(3)-ld(1)+ld(8)*ld(3))"); // d
  setup.push("st(3,ld(5)-ld(1)+ld(9)*ld(5))"); // e
  const sourceSense = !o.sense || o.sense === "source" || o.sense === "0";
  const divisor = sourceSense ? "(ld(8)*X/W+ld(9)*Y/H+1)"
    : "((ld(6)-ld(8)*X)*(ld(3)-ld(9)*Y)-(ld(7)-ld(9)*X)*(ld(2)-ld(8)*Y))";
  const sx = sourceSense ? `(ld(6)*X/W+ld(7)*Y/H+ld(0))/${divisor}`
    : `W*((X-ld(0))*(ld(3)-ld(9)*Y)-(ld(7)-ld(9)*X)*(Y-ld(1)))/${divisor}`;
  const sy = sourceSense ? `(ld(2)*X/W+ld(3)*Y/H+ld(1))/${divisor}`
    : `H*((ld(6)-ld(8)*X)*(Y-ld(1))-(X-ld(0))*(ld(2)-ld(8)*Y))/${divisor}`;
  setup.push(`st(4,${sx})`, `st(5,${sy})`);
  const cubic = o.interpolation === "cubic" || o.interpolation === "1";
  const channel = (name: string) => escapeExpression(`${setup.join(";")};if(gt(abs(${divisor}),.000000000001),${sample(name, cubic)},0)`);
  return `geq=r='${channel("r")}':g='${channel("g")}':b='${channel("b")}':a='${channel("alpha")}':interpolation=${cubic ? "nearest" : "bilinear"}`;
}
